"""Compile verified HTTPS cookie creation, replay and deletion."""
from pathlib import Path
import argparse,hashlib,json,os,re,subprocess
from pmf_compiler import resolve_compiler

def build(compiler,out):
    root=Path(__file__).resolve().parents[1];out.mkdir(parents=True,exist_ok=False)
    cases=['set','echo','delete','empty']
    names=['Anvil/Network/web_url.pbi','Anvil/Network/web_request.pbi','Anvil/Network/web_response.pbi','Anvil/Network/web_transport.pbi','Anvil/Network/web_client.pbi','Anvil/Network/web_cookie_date.pbi','Anvil/Network/web_cookies.pbi','Anvil/Network/web_cookie_response.pbi','RaspberryPi4/Lib/mmu.pi4']
    s='#WEB_KERNEL_BINDING=0\n'+'\n'.join('XIncludeFile "'+n+'"' for n in names)+'\nGlobal u.WebUrl\nGlobal q.WebRequest\nGlobal a.WebResponse\nGlobal client.WebClient\nGlobal jar.WebCookies\nGlobal Dim storage.a[4*#WEB_COOKIE_STRIDE]\nGlobal Dim host.a[256]\nGlobal Dim target.a[1024]\nGlobal Dim qh.a[2048]\nGlobal Dim ah.a[4096]\nGlobal Dim line.a[1024]\nGlobal Dim tx.a[512]\nGlobal Dim rx.a[512]\nGlobal Dim output.a[64]\nGlobal Dim scratch.a[2048]\nGlobal *wirePet,*wireTime\nGlobal wtable.i\nProcedure CaptureTable()\n ASM\n adrp x1, global_wtable\n add x1, x1, #:lo12:global_wtable\n str x0, [x1]\n EndASM\nEndProcedure\nProcedure.i Main()\n Define i.i,j.i,rc.i,start.i,n.i,v.i,p.i,step.i,length.i,k.i,now.i,captured.i,sent.i\n CaptureTable()\n For i=0 To 32767 : PokeA($E1C00000+i,0) : Next\n PokeI($E1C00000,$57434B32)\n rc=WebPayloadBind(wtable) : If rc<>0 : ProcedureReturn 1 : EndIf\n wirePet=PeekI(wtable+16+6*8) : wireTime=PeekI(wtable+16+11*8)\n MmuClearNc() : MmuAddNc($08A00000,$09200000) : MmuAddNc($08100000,$08180000)\n rc=MmuBuildTables($4F80000) : If rc<>0 : ProcedureReturn 2 : EndIf\n MmuEnableCached()\n rc=WebCookiesInit(@jar,@storage[0],4,0)\n For i=0 To 3\n  p=$E1C00100+i*4096 : length=0\n  u\\host=@host[0] : u\\hostCapacity=256 : u\\target=@target[0] : u\\targetCapacity=1024\n  If i=0\n   v="https://httpbingo.org/response-headers?Set-Cookie=anvil_session%3Dready%3B%20Path%3D%2F%3B%20Secure%3B%20HttpOnly%3B%20Max-Age%3D120"\n  ElseIf i=2\n   v="https://httpbingo.org/response-headers?Set-Cookie=anvil_session%3Dgone%3B%20Path%3D%2F%3B%20Secure%3B%20Max-Age%3D0"\n  Else\n   v="https://httpbingo.org/cookies"\n  EndIf\n  n=0 : While PeekA(v+n)<>0 : n=n+1 : Wend\n  rc=WebUrlParse(v,n,1,@u)\n  If rc=0 : rc=WebRequestInit(@q,@u,"GET",3,0,0,@qh[0],2048) : EndIf\n  If rc=0 : rc=WebRequestHeader(@q,"User-Agent",10,"Anvil",5) : EndIf\n  If rc=0 : rc=WebRequestHeader(@q,"Accept-Encoding",15,"identity",8) : EndIf\n  sent=0\n  If rc=0 And i>0\n   sent=WebCookieHeader(@jar,@u,now,1,0,@scratch[0],2048)\n   If sent<0 : rc=sent : EndIf\n   wckWipe(@scratch[0],2048)\n  EndIf\n  If rc=0 : rc=WebRequestHeader(@q,"Cookie",6,"stale=discard",13) : EndIf\n  If rc=0 : rc=WebRequestHeader(@q,"cOOkie",6,"duplicate=discard",17) : EndIf\n  If rc=0 And i % 2=0 : rc=WebCookiesApply(@jar,@u,@q,now,1,0,@scratch[0],2048) : EndIf\n  If rc=0 : rc=WebRequestFinishHeaders(@q) : EndIf\n  If rc=0 And i % 2=1 : rc=WebCookiesApply(@jar,@u,@q,now,1,0,@scratch[0],2048) : EndIf\n  If rc=0 : rc=WebResponseInit(@a,@line[0],1024,@ah[0],4096,0) : EndIf\n  start=wireTime()/1000\n  If rc=0 : rc=WebClientStart(@client,@u,@q,@a,@tx[0],512,@rx[0],512,start,20000) : EndIf\n  While rc=0\n   wirePet() : WebPayloadService(1)\n   step=WebClientStep(@client,0,0,1,@output[0],31,wireTime()/1000)\n   n=client\\written\n   If length+n>3072 : rc=-993 : Break : EndIf\n   For j=0 To n-1 : PokeA(p+64+length+j,output[j]) : Next\n   length=length+n\n   If step<>0 : rc=step : Break : EndIf\n  Wend\n  captured=-1\n  If rc=1\n   n=WebResponseHeader(@a,"date",0,@scratch[0],2048)\n   If n<0 : rc=n : Else : now=WebCookieDate(@scratch[0],n) : If now<0 : rc=-994 : EndIf : EndIf\n   If rc=1 : captured=WebCookiesCapture(@jar,@u,@a,now,@scratch[0],2048) : If captured<0 : rc=captured : EndIf : EndIf\n  EndIf\n  PokeI(p,rc) : PokeI(p+8,a\\status) : PokeI(p+16,wireTime()/1000-start) : PokeI(p+24,length) : PokeI(p+32,sent) : PokeI(p+40,captured) : PokeI(p+48,now)\n  WebClientClose(@client) : wckWipe(@qh[0],2048) : wckWipe(@ah[0],4096) : wckWipe(@scratch[0],2048)\n  If rc<0 : Break : EndIf\n Next\n PokeI($E1C00008,rc)\n rc=WebCookiesClear(@jar)\n For i=0 To 4*#WEB_COOKIE_STRIDE-1 : If storage[i]<>0 : rc=-995 : EndIf : Next\n PokeI($E1C00010,rc)\n MmuDisableCachedFlushed() : ProcedureReturn 0\nEndProcedure\n'
    source=out/'proof.pi4';source.write_text(s,encoding='utf8')
    q=subprocess.run([str(resolve_compiler(compiler)),'--compile',str(source),'-t','pi4','--load-addr','0x1000000','--stack-addr','0x4f00000','--entry-returns','--wants-services','-o',str(out/'proof.img')],env=dict(os.environ,PMF_ROOT=str(root)),capture_output=True,text=True,encoding='utf8',timeout=180,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
    log=q.stdout+q.stderr;(out/'compile.txt').write_text(log,encoding='utf8');print(log[-1800:]);assert q.returncode==0
    code=re.search(r'occupying \$([0-9A-Fa-f]+)\.\.\$([0-9A-Fa-f]+)',log);bss=re.search(r'bss \$([0-9A-Fa-f]+)\.\.\$([0-9A-Fa-f]+)',log)
    payload=(out/'proof.img.pmf').read_bytes();ranges={'code':['0x'+x for x in code.groups()],'bss':['0x'+x for x in bss.groups()],'stack':['0x4e00000','0x4efffff'],'report':['0xe1c00000','0xe1c07fff'],'tables':['0x4f80000','0x4f82fff']}
    (out/'identity.json').write_text(json.dumps(dict(bytes=len(payload),sha256=hashlib.sha256(payload).hexdigest(),checked_ranges=ranges,source_hashes={n:hashlib.sha256((root/n).read_bytes()).hexdigest() for n in names},cases=cases),indent=2),encoding='utf8')
if __name__=='__main__':
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--compiler',required=True);ap.add_argument('--out',type=Path,required=True)
    args=ap.parse_args();build(args.compiler,args.out.resolve())
